INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine Code-Überprüfung nur Fehler findet?', 2, '[{"text": "Nein", "correct": true, "because": "Verbessert auch Lesbarkeit und Struktur"}, {"text": "Ja", "correct": false, "because": "Mehr als nur Fehlerfindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich bei der Überprüfung von Software?', 3, '[{"text": "Qualitätssicherung", "correct": true, "because": "Findet Fehler und Schwächen"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Fokus auf Qualität"}, {"text": "Dokumentation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei einer Code-Überprüfung wichtig?', 5, '[{"text": "Lesbarkeit", "correct": true, "because": "Fördert Wartbarkeit"}, {"text": "Funktionalität", "correct": true, "because": "Sichert Korrektheit"}, {"text": "Farbschema", "correct": false, "because": "Kosmetisch"}, {"text": "Dateigröße", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Code-Überprüfungen fördern Teamarbeit. b) Sie ersetzen automatisierte Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Tests sind ergänzend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Überprüfung von Software?', 4, '[{"text": "Code-Stil", "correct": false, "because": "Wichtig für Lesbarkeit"}, {"text": "Testabdeckung", "correct": false, "because": "Zeigt Zuverlässigkeit"}, {"text": "Entwicklername", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Überprüfung immer vor der Veröffentlichung stattfindet?', 2, '[{"text": "Nein", "correct": true, "because": "Kann jederzeit erfolgen"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode verbessert die Effektivität einer Code-Überprüfung?', 4, '[{"text": "Checklisten", "correct": true, "because": "Strukturiert den Prozess"}, {"text": "Schnelles Durchsehen", "correct": false, "because": "Zu oberflächlich"}, {"text": "Manuelle Tests", "correct": false, "because": "Ergänzend, nicht Kern"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Überprüfungen nur für große Projekte nötig sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Überprüfung nur für Code relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Prozesse, Dokumente"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Überprüfung erfolgreich?', 5, '[{"text": "Klarer Fokus", "correct": true, "because": "Hält Ziel im Blick"}, {"text": "Offenes Feedback", "correct": true, "because": "Fördert Verbesserungen"}, {"text": "Hohe Teilnehmerzahl", "correct": false, "because": "Kann ineffizient sein"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Überprüfung eines Prozesses?', 4, '[{"text": "Effizienzlücken finden", "correct": true, "because": "Verbessert Abläufe"}, {"text": "Schnelles Abschließen", "correct": false, "because": "Tiefe wichtiger"}, {"text": "Teamgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Peer-Überprüfungen fördern Qualität. b) Sie brauchen immer externe Experten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, intern möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine effektive Code-Überprüfung?', 3, '[{"text": "Klar definierte Kriterien", "correct": false, "because": "Sichert Fokus"}, {"text": "Kommunikation", "correct": false, "because": "Fördert Verständnis"}, {"text": "Luxuriöse Tools", "correct": true, "because": "Einfache Tools reichen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich eine Überprüfung strukturiere?', 4, '[{"text": "Mit Checkliste und Feedbackrunde", "correct": true, "because": "Sichert Vollständigkeit"}, {"text": "Nur spontan diskutieren", "correct": false, "because": "Fehlt Struktur"}, {"text": "Ohne Kriterien", "correct": false, "because": "Unklarer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Überprüfungen Zeitverschwendung sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Verbessern Qualität langfristig"}, {"text": "Ja", "correct": false, "because": "Bringen nachweisbare Vorteile"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, Überprüfungen konstruktiv zu gestalten?', 4, '[{"text": "Fokus auf Lösungen", "correct": true, "because": "Fördert Verbesserungen"}, {"text": "Schuldzuweisungen", "correct": false, "because": "Kontraproduktiv"}, {"text": "Schnelles Urteil", "correct": false, "because": "Fehlt Tiefe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Werden Überprüfungen immer von Einzelpersonen gemacht?', 2, '[{"text": "Nein", "correct": true, "because": "Teams oder Peers möglich"}, {"text": "Ja", "correct": false, "because": "Oft kollaborativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine regelmäßige Überprüfung?', 5, '[{"text": "Früherkennung von Fehlern", "correct": true, "because": "Vermeidet spätere Kosten"}, {"text": "Wissenstransfer", "correct": true, "because": "Fördert Lernen"}, {"text": "Schnellere Releases", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Überprüfung unwichtig?', 3, '[{"text": "Feedbackkultur", "correct": false, "because": "Fördert Offenheit"}, {"text": "Klarer Rahmen", "correct": false, "because": "Sichert Struktur"}, {"text": "Kaffeepausenlänge", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich Code überprüfe?', 4, '[{"text": "Strukturierte Checkliste nutzen", "correct": true, "because": "Sichert Gründlichkeit"}, {"text": "Nur Fehler zählen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Feedback", "correct": false, "because": "Verpasst Verbesserungen"}]');
